use serde::{Deserialize, Serialize};
use std::collections::HashMap;

mkdeclimpl! {
impl < S : Idx > SccData < S > { # [doc = " Number of SCCs,"] fn len (& self) -> usize { self . scc_details . len () } # [doc = " Returns the successors of the given SCC."] fn successors (& self , scc : S) -> & [S] { & self . all_successors [self . scc_details [scc] . range . clone ()] } # [doc = " Creates a new SCC with `successors` as its successors and"] # [doc = " returns the resulting index."] fn create_scc (& mut self , successors : impl IntoIterator < Item = S >) -> S { let all_successors_start = self . all_successors . len () ; self . all_successors . extend (successors) ; let all_successors_end = self . all_successors . len () ; debug ! ("create_scc({:?}) successors={:?}" , self . len () , & self . all_successors [all_successors_start .. all_successors_end] ,) ; let range = all_successors_start .. all_successors_end ; let metadata = SccDetails { range } ; self . scc_details . push (metadata) } }
}